// Тема приходит в теле POST-запроса параметром topic.
// Проверяем её здесь: пустой запрос иначе дошёл бы до модели и стоил денег впустую.
const body = $input.first().json.body ?? $input.first().json;
const topic = (body.topic ?? '').toString().trim();
if (!topic) {
  throw new Error('В запросе нет параметра topic');
}
const style = (body.style ?? '').toString().trim();
const task = style
  ? `Напиши пост для Telegram-канала на тему: ${topic}. Стиль: ${style}.`
  : `Напиши пост для Telegram-канала на тему: ${topic}.`;
return [{ json: { topic, style, task } }];

// Ответ модели лежит во вложенной структуре — добираемся по индексу [0].
const out = $input.first().json;
let text = out?.choices?.[0]?.message?.content
        ?? out?.message?.content
        ?? '';
text = text.toString().trim();
if (!text) {
  throw new Error('Модель вернула пустой текст: ' + JSON.stringify(out).slice(0, 300));
}
// У обычного сообщения Telegram предел 4096 знаков, у подписи к фото — 1024.
// Поэтому меряем дважды: сам текст и отдельно пригодность его как подписи.
const TG_TEXT_LIMIT = 4096;
const TG_CAPTION_LIMIT = 1024;
if (text.length > TG_TEXT_LIMIT - 96) { text = text.slice(0, TG_TEXT_LIMIT - 99) + '...'; }
const fitsCaption = text.length <= TG_CAPTION_LIMIT;
// Не поместился — фото уходит без подписи, а текст следом отдельным сообщением.
const caption = fitsCaption ? text : '';
const topic = $('Prepare Prompt').first().json.topic;
return [{ json: { topic, text, caption, needsFollowup: !fitsCaption, length: text.length } }];

// Модели рисования обрезают промпт (у dall-e-3 предел 1000 знаков),
// поэтому задание художнику укорачиваем заранее: лучше короткий бриф,
// чем ошибка 400 после того, как текст поста уже оплачен.
const IMAGE_PROMPT_LIMIT = 900;
const out = $input.first().json;
let prompt = (out?.choices?.[0]?.message?.content ?? out?.message?.content ?? '')
  .toString().trim().replace(/^["«']+|["»']+$/g, '');
if (!prompt) {
  // Модель промолчала — рисуем хотя бы по теме поста, а не падаем.
  prompt = `minimal flat vector illustration about ${$('Prepare Prompt').first().json.topic},`
         + ' clean, professional, blue and white palette, no text';
}
if (prompt.length > IMAGE_PROMPT_LIMIT) { prompt = prompt.slice(0, IMAGE_PROMPT_LIMIT); }
return [{ json: { imagePrompt: prompt, imagePromptLength: prompt.length } }];

