// Собираем понятный ответ вызывающему: опубликовано или нет, и ссылку на пост.
const tg = $('Send Photo — Telegram API').first().json;
const parsed = $('Parse Response').first().json;
const brief = $('Prepare Image Brief').first().json;
const ok = tg?.ok === true;
const msg = tg?.result ?? {};
const chat = msg?.chat ?? {};
const url = chat.username && msg.message_id
  ? `https://t.me/${chat.username}/${msg.message_id}`
  : null;
return [{ json: {
  ok,
  published: ok,
  topic: parsed.topic,
  length: parsed.length,
  with_image: ok && Array.isArray(msg.photo) && msg.photo.length > 0,
  caption_used: parsed.caption.length > 0,
  text_sent_separately: parsed.needsFollowup,
  image_prompt_length: brief.imagePromptLength,
  message_id: msg.message_id ?? null,
  channel: chat.title ?? chat.username ?? null,
  url,
  error: ok ? null : (tg?.description ?? 'Telegram отклонил публикацию'),
} }];
